Lemma goodframe_false : forall lo v top, goodframe lo v top = false <-> ~ (lo < v /\ v < top - 16 /\ v mod 8 = 0).
Proof.
  intros. rewrite <- goodframe_true. destruct (goodframe lo v top); split; congruence.
Qed.

