  (* [comment removed for export] *)
  Ltac uf_exit_last CASES EQ2 :=
    let G := fresh "G" in
    destruct CASES as [[G ->]|[G ?]];
    [ rewrite uloop_last by (unfold KPAGE; lia); rewrite <- EQ2; eapply uf_exit; eassumption
    | exfalso; apply goodframe_true in G; try rewrite land7_mod8 in *; lia ].
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

  (* [comment removed for export] *)
  Lemma uf_loop : forall CH f (acc : list Z) (m1 : word -> option byte)
      (t0 t1 t2 a6 a7 x18 x19 x20 x21 x22 t3 t4 t5 t6 : word),
    frame_chain bsegs m1 TOP f CH ->
    bp <= f -> 0 <= f < 2^64 ->
    (forall x, In x acc -> 0 <= x < 2^64) ->
    (1 <= length acc)%nat -> Z.of_nat (length acc) <= MD ->
    rw_cells bsegs m1 (bv_unsigned sp + -64) [C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk bsegs m1 lo (bv_unsigned sp + -64) ->
    munch W m m1 -> wmono bsegs m m1 -> mem_inv bsegs m1 ->
    rw_cells bsegs m1 (OBJ + 8) [C4 (wz (Z.of_nat (length acc)))] ->
    u64arr bsegs m1 (OBJ + 16) (map wz acc ++ skipn (length acc) buf) ->
    evt bsegs (POST (uloop pc0 MD CH acc))
      (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz MD) (wz (TOP - 16)) (wz OBJ) (wz pc0) (wz f) (wz KPAGE)
               (wz (OBJ + 16)) (wz (Z.of_nat (length acc))) a6 a7 x18 x19 x20 x21 x22 s7 s8 s9 s10 s11 t3 t4 t5 t6)
